3	 * @change 2026-11-07 FR-FRENEMY-117, TR-FRENEMY-ORCH-121,
4	 * TEST-FRENEMY-117, AC-TEST-FRENEMY-117-Q01 through Q05 and
5	 * AC-TEST-FRENEMY-117-06 through 08: Added deterministic scripted evidence and
6	 * deliberate negative controls that remain reproducible without harvested live
7	 * data or integration artifacts.
8	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-08: Prove that an
9	 * actual receipt member substitution fails while harmless member reordering passes.
10	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 through 08:
11	 * Prove per-question stop behavior, transcript/tool/result binding, and exact
12	 * ZIP-derived passed and failed archive evidence with byte-level controls.
13	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 and 08: Added
14	 * direct controls for transcript results, Cline identity, orchestration pairs,
15	 * per-question stop branches, required report members, and ZIP parser guards.
16	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 and 07: Made
17	 * the assertion inventory consume messages from controls that actually reached
18	 * each assertion occurrence, and added loader and per-question branch controls.
19	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 through 08:
20	 * Record direct controls only when their named subtests execute, inventory
21	 * assertion occurrences one-for-one, and reject incomplete failed-run archives.
22	 * @change 2026-11-09 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 and 07: Added
23	 * direct negative controls for every previously justified but directly reachable
24	 * session, transcript, per-question participant, effort, and manifest assertion.
25	 */
26	import assert from "node:assert/strict";
27	import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
28	import { tmpdir } from "node:os";
29	import { dirname, join } from "node:path";
30	import { fileURLToPath } from "node:url";
31	import test from "node:test";
32	import {
33	  assertFourAgentArchiveEvidence,
34	  assertFourAgentEvidence,
35	  createScriptedEvidence,
36	  deriveArchiveEvidence,
37	  loadQuestionFixture,
38	  runQuestionSequence,
39	  sha256,
40	} from "../contracts/four-agent-reasoning.mjs";
41	import { createDeflatedZip, createStoredZip, inspectZipArchive } from "../contracts/zip-archive.mjs";
42	
43	const here = dirname(fileURLToPath(import.meta.url));
44	const fixturePath = join(here, "..", "fixtures", "four-agent-reasoning-questions.json");
45	const fixture = loadQuestionFixture(fixturePath);
46	
47	function collectLiteralAssertionMessages(source) {
48	  const messages = [];
49	  const callPattern = /assert\.(?:ok|equal|notEqual|deepStrictEqual|match)\(/gu;
50	  for (const match of source.matchAll(callPattern)) {
51	    let depth = 1;
52	    let quote = null;
53	    let escaped = false;
54	    let index = match.index + match[0].length;
55	    const topLevelCommas = [];
56	    for (; index < source.length && depth > 0; index += 1) {
57	      const character = source[index];
58	      if (quote) {
59	        if (escaped) escaped = false;
60	        else if (character === "\\") escaped = true;
61	        else if (character === quote) quote = null;
62	        continue;
63	      }
64	      if (["\"", "'", "`"].includes(character)) {
65	        quote = character;
66	        continue;
67	      }
68	      if (character === "(") depth += 1;
69	      else if (character === ")") depth -= 1;
70	      else if (character === "," && depth === 1) topLevelCommas.push(index);
71	    }
72	    if (topLevelCommas.length === 0) continue;
73	    let candidateEnd = index - 1;
74	    if (source.slice(topLevelCommas.at(-1) + 1, candidateEnd).trim() === "") candidateEnd = topLevelCommas.pop();
75	    if (topLevelCommas.length === 0) continue;
76	    const candidate = source.slice(topLevelCommas.at(-1) + 1, candidateEnd).trim();
77	    const delimiter = candidate[0];
78	    if (!["\"", "'", "`"].includes(delimiter) || candidate.at(-1) !== delimiter) continue;
79	    const message = delimiter === "\""
80	      ? JSON.parse(candidate)
81	      : candidate.slice(1, -1).replace(/\$\{[^}]+\}/gu, "*");
82	    messages.push(message);
83	  }
84	  return messages;
85	}
