100	  const events = evidence.files[session.transcriptPath].split(/\r?\n/u).filter(Boolean).map((line) => JSON.parse(line));
101	  const index = events.findIndex(eventPredicate);
102	  assert.ok(index >= 0, "scripted transcript event for removal was not found");
103	  events.splice(index, 1);
104	  evidence.files[session.transcriptPath] = `${events.map((event) => JSON.stringify(event)).join("\n")}\n`;
105	}
