124	  const validationReceipt = {
125	    ...evidence.archive.validationReceipt,
126	    zipSha256: sha256(bytes),
127	    manifestSha256: sha256(manifestText),
128	    memberCount: archiveEntries.length,
129	    members: archiveEntries.map(([path]) => path),
