1	/**
2	 * @file Shared four-agent reasoning fixture, evidence, and validation contract.
3	 * @change 2026-11-07 FR-FRENEMY-117, TR-FRENEMY-ORCH-121,
4	 * TEST-FRENEMY-117, AC-FRENEMY-117-01 through AC-FRENEMY-117-05,
5	 * AC-TR-FRENEMY-ORCH-121-01 through AC-TR-FRENEMY-ORCH-121-06, and
6	 * AC-TEST-FRENEMY-117-Q01 through Q05 and AC-TEST-FRENEMY-117-06 through 08:
7	 * Added the canonical question projection, independent scripted evidence,
8	 * strict peer-judgment gate, session inventory, and review-archive contract.
9	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-08: Compare
10	 * archive receipt members as an exact set so ZIP enumeration order is irrelevant.
11	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 through 08:
12	 * Bind per-question advancement to complete judgment and transcript evidence,
13	 * and derive exact archive evidence from validated ZIP bytes.
14	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06: Bind Cline
15	 * relay requests to the configured provider and model so substituted execution
16	 * settings are rejected by the same transcript contract.
17	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 through 08:
18	 * Bind every retained transcript to session inventory, orchestration evidence,
19	 * and summary counts for passed and failed archives.
20	 */
21	import assert from "node:assert/strict";
22	import { createHash } from "node:crypto";
23	import { readFileSync } from "node:fs";
24	import { inspectZipArchive } from "./zip-archive.mjs";
25	
26	export const PARTICIPANTS = Object.freeze(["claude", "codex", "grok", "cline"]);
27	export const EXPECTED_COUNTS = Object.freeze({ questions: 5, answers: 20, sessions: 40, judgments: 60 });
28	export const EXPECTED_AC_SHA256 = Object.freeze({
29	  Q01: "187C6F9D3D571E4E4642ADC0F5441B8719852322FDBC952ABC8F672F2DD7ED89",
30	  Q02: "20B47268ADD6F2A2F269B660F16A5548429599A1ACCABD6E2A09924C9DD19ACB",
31	  Q03: "D636555339A80AE68F1C461B46C59B96AAC4065B1F5ED41FEB8041999D6BFFA0",
32	  Q04: "7B55E71719FD2CB41CDFDFC71480EC1F39B0A7EFEE300F0235B885F732F765C5",
33	  Q05: "1F8A281A2D98D6A41B5BE0933EBAD955D4294ED0A80265B5EB331E868A47386B",
34	});
35	const READ_ONLY_TOOLS = Object.freeze({ claude: "ask_claude", grok: "ask_grok", cline: "ask_cline" });
36	
37	/** Return an uppercase SHA-256 digest for UTF-8 text. */
38	export function sha256(value) {
39	  return createHash("sha256").update(value, typeof value === "string" ? "utf8" : undefined).digest("hex").toUpperCase();
40	}
41	
42	/** Load and validate the version-controlled projection of TEST-FRENEMY-117. */
43	export function loadQuestionFixture(path) {
44	  const fixture = JSON.parse(readFileSync(path, "utf8"));
45	  assert.equal(fixture.requirementId, "TEST-FRENEMY-117", "wrong fixture requirement identity");
46	  assert.equal(fixture.effort, "medium", "fixture effort must be medium");
47	  assert.deepStrictEqual(fixture.participants, PARTICIPANTS, "fixture participant identities drifted");
48	  assert.equal(fixture.questions.length, EXPECTED_COUNTS.questions, "fixture must contain five questions");
49	  assert.equal(new Set(fixture.questions.map(({ id }) => id)).size, EXPECTED_COUNTS.questions, "question identities must be unique");
50	  for (const question of fixture.questions) {
51	    assert.match(question.id, /^Q0[1-5]$/u, "invalid question identity");
52	    assert.equal(question.acceptanceCriterionId, `AC-TEST-FRENEMY-117-${question.id}`, "loader question AC identity drifted");
53	    assert.ok(question.question.trim(), `${question.id} question is empty`);
54	    assert.ok(question.rubric.trim(), `${question.id} rubric is empty`);
55	    assert.equal(question.acceptanceCriterionSha256, EXPECTED_AC_SHA256[question.id], `${question.id} loader canonical AC hash drifted`);
56	    assert.equal(sha256(question.acceptanceCriterionText), question.acceptanceCriterionSha256, `${question.id} loader AC projection hash mismatch`);
57	    assert.ok(question.acceptanceCriterionText.includes(`\"${question.question}\"`), `${question.id} loader exact question is not present in the AC projection`);
58	    const canonicalRubric = question.acceptanceCriterionText.match(/ Canonical rubric: (.+)$/u)?.[1];
59	    assert.ok(canonicalRubric, `${question.id} loader canonical rubric is missing from the AC projection`);
60	    assert.equal(canonicalRubric.toLocaleLowerCase("en-US"), question.rubric.toLocaleLowerCase("en-US"), `${question.id} loader rubric drifted from the AC projection`);
61	  }
62	  return fixture;
63	}
64	
65	function jsonLine(value) {
66	  return `${JSON.stringify(value)}\n`;
67	}
68	
69	/** Build the exact answer prompt retained by both scripted and live sessions. */
70	export function answerPrompt(agent, question) {
71	  return [
72	    `You are the ${agent} participant in a controlled four-agent reasoning integration test.`,
73	    "Use medium reasoning effort. This question is self-contained.",
74	    "Do not inspect the workspace, browse, invoke tools, delegate, or modify files.",
75	    `Question ID: ${question.id}`,
76	    `Acceptance criterion: ${question.acceptanceCriterionId}`,
77	    `Subject: ${question.subject}`,
78	    `Question: ${question.question}`,
79	    "Return a concise answer with enough reasoning to make the calculation or causal argument reviewable.",
80	  ].join("\n");
81	}
82	
83	/** Build the exact peer-review prompt retained by both scripted and live sessions. */
84	export function reviewPrompt(reviewerAgent, question, answers) {
85	  const subjects = answers.filter(({ agent }) => agent !== reviewerAgent).map(({ agent, answer }) => ({ subjectAgent: agent, answer }));
86	  return [
87	    `You are the ${reviewerAgent} peer reviewer in a controlled four-agent reasoning integration test.`,
88	    "Use medium reasoning effort. Do not inspect the workspace, browse, invoke tools, delegate, or modify files.",
89	    `Question ID: ${question.id}`,
90	    `Acceptance criterion: ${question.acceptanceCriterionId}`,
91	    `Question: ${question.question}`,
92	    `Canonical rubric: ${question.rubric}`,
93	    `Answers to review: ${JSON.stringify(subjects)}`,
94	    "Return only a JSON array of exactly three objects, with no markdown or surrounding text.",
95	    "Each object must contain questionId, subjectAgent, reviewerAgent, integer accuracy from 0 through 100, nonempty rationale, and nonempty rubricFindings array.",
96	    `Every reviewerAgent must be ${JSON.stringify(reviewerAgent)} and no subjectAgent may be ${JSON.stringify(reviewerAgent)}.`,
97	  ].join("\n");
98	}
99	
100	function buildTranscript(runId, question, agent, role, payload, prompt) {
101	  const sessionId = `${runId}-${question.id}-${agent}-${role}`;
102	  const base = { runId, questionId: question.id, phase: role, agent, sessionId };
103	  const resultText = role === "answer" ? payload.answer : JSON.stringify(payload);
104	  const request = agent === "codex"
