278	function assertSessionTranscript({ question, answers, judgments, session, files }) {
279	  assert.equal(session.transcriptComplete, true, "session transcript is incomplete");
280	  assert.ok(Object.hasOwn(files, session.transcriptPath), "session transcript is missing");
281	  const transcript = parseJsonLines(files[session.transcriptPath], "session transcript is empty");
282	  assert.ok(transcript.every((item) => item.questionId === session.questionId && item.agent === session.agent && item.sessionId === session.sessionId), "session transcript identity does not match its session");
283	  const exit = transcript.find((item) => item.eventType === "session_exit");
284	  assert.ok(exit, "session transcript has no exit event");
285	  assert.equal(exit.payload?.code, 0, "session transcript exit code is not zero");
286	
287	  const expectedPrompt = session.role === "answer"
288	    ? answerPrompt(session.agent, question)
289	    : reviewPrompt(session.agent, question, answers);
290	  assert.ok(typeof session.resultText === "string" && session.resultText.trim(), "session result text is missing");
291	
292	  if (session.agent === "codex") {
293	    const request = transcript.find((item) => item.direction === "request" && item.eventType === "codex_prompt");
294	    assert.ok(request, "session transcript has no Codex prompt request");
295	    assert.equal(request.payload?.prompt, expectedPrompt, "Codex session prompt does not match the exact question and rubric");
296	    const sandboxIndex = request.payload?.argv?.indexOf("--sandbox") ?? -1;
297	    assert.ok(sandboxIndex >= 0 && request.payload.argv[sandboxIndex + 1] === "read-only", "Codex argv does not use the read-only sandbox");
298	    assert.ok(request.payload.argv.includes("model_reasoning_effort=medium"), "Codex argv does not request medium effort");
299	    const result = transcript.find((item) => item.direction === "response" && item.eventType === "agent_result");
300	    assert.ok(result, "session transcript has no retained agent result");
301	    assert.equal(result.payload?.text, session.resultText, "Codex session transcript result differs from retained result text");
302	  } else {
303	    const request = transcript.find((item) => item.direction === "request" && item.eventType === "relay_jsonrpc" && item.payload?.method === "tools/call");
304	    assert.ok(request, "session transcript has no relay tools/call request");
305	    assert.equal(request.payload.params?.name, READ_ONLY_TOOLS[session.agent], "relay request did not use the agent read-only tool");
306	    assert.equal(request.payload.params?.arguments?.prompt, expectedPrompt, "relay session prompt does not match the exact question and rubric");
307	    assert.equal(request.payload.params?.arguments?.effort, "medium", "relay request effort is not medium");
308	    if (session.agent === "cline") {
309	      assert.equal(request.payload.params?.arguments?.provider, "openai-codex", "Cline relay provider was substituted");
310	      assert.equal(request.payload.params?.arguments?.model, "gpt-5.6-luna", "Cline relay model was substituted");
311	    }
312	    const response = transcript.find((item) => item.direction === "response" && item.eventType === "relay_jsonrpc" && item.payload?.id === request.payload.id);
313	    assert.ok(response, "relay tools/call request has no matched response");
314	    assert.equal(response.payload.result?.isError, false, "relay tools/call response is an error");
315	    assert.equal(response.payload.result?.content?.[0]?.text, session.resultText, "relay session transcript result differs from retained result text");
316	  }
317	
318	  if (session.role === "answer") {
319	    const answer = answers.find(({ agent }) => agent === session.agent);
320	    assert.ok(answer, "answer session has no retained answer");
321	    assert.equal(answer.answer, session.resultText, "retained answer differs from its session transcript result");
322	  } else {
323	    const expected = judgments.filter(({ reviewerAgent }) => reviewerAgent === session.agent);
324	    assert.deepStrictEqual(JSON.parse(session.resultText), expected, "parsed judgments differ from the session transcript result");
325	  }
326	}
