424	export function assertQuestionEvidence({ question, answers, judgments, sessions, files }) {
425	  assert.equal(answers.length, PARTICIPANTS.length, `${question.id} answer set is incomplete`);
426	  assert.deepStrictEqual(new Set(answers.map(({ agent }) => agent)), new Set(PARTICIPANTS), `${question.id} answer participants are incomplete`);
427	  for (const answer of answers) {
428	    assert.equal(answer.questionId, question.id, `${question.id} answer has wrong question identity`);
429	    assert.equal(answer.effort, "medium", `${question.id} answer effort is not medium`);
430	    assert.equal(answer.status, "completed", `${question.id} answer record status is not completed`);
431	    assert.ok(answer.answer.trim(), `${question.id} answer is empty`);
432	  }
433	  assert.equal(judgments.length, PARTICIPANTS.length * (PARTICIPANTS.length - 1), `${question.id} judgment set is incomplete`);
434	  const judgmentKeys = new Set();
435	  for (const judgment of judgments) assertJudgment(judgment, judgmentKeys);
436	  const answerSessions = sessions.filter(({ role }) => role === "answer");
437	  const reviewSessions = sessions.filter(({ role }) => role === "review");
438	  assert.equal(answerSessions.length, PARTICIPANTS.length, `${question.id} answer sessions are incomplete`);
439	  assert.equal(reviewSessions.length, PARTICIPANTS.length, `${question.id} review sessions are incomplete`);
440	  assert.deepStrictEqual(new Set(answerSessions.map(({ agent }) => agent)), new Set(PARTICIPANTS), `${question.id} answer-session participants are incomplete`);
441	  assert.deepStrictEqual(new Set(reviewSessions.map(({ agent }) => agent)), new Set(PARTICIPANTS), `${question.id} review-session participants are incomplete`);
442	  for (const answer of answers) {
443	    const session = answerSessions.find(({ agent }) => agent === answer.agent);
444	    assert.ok(session, `${question.id} answer has no matching session`);
445	    assert.equal(answer.sessionId, session.sessionId, `${question.id} answer sessionId does not match its session`);
446	  }
447	  for (const session of reviewSessions) {
448	    const expected = judgments.filter(({ reviewerAgent }) => reviewerAgent === session.agent);
449	    assert.equal(expected.length, PARTICIPANTS.length - 1, `${question.id} reviewer judgment count is wrong`);
450	    assert.deepStrictEqual(session.judgments, expected, `${question.id} reviewer judgments do not match the review session`);
451	  }
452	  for (const session of sessions) {
453	    assert.equal(session.questionId, question.id, `${question.id} session has wrong question identity`);
454	    assert.equal(session.effort, "medium", `${question.id} session effort is not medium`);
455	    assert.equal(session.status, "completed", `${question.id} retained session status is not completed`);
456	    assertSessionTranscript({ question, answers, judgments, session, files });
