488	    archive: {
489	      readable: true,
490	      sha256: sha256(zipBytes),
491	      members: [...archiveFiles.keys()],
492	      validationReceipt,
493	    },
494	  };
495	}
496	
497	/** Validate the finalized manifest and archive receipt after real archive creation. */
498	export function assertFourAgentArchiveEvidence(evidence) {
499	  const requiredFiles = ["reports/four-agent.node.junit.xml", "reports/Frenemy.Relay.IntegrationTests.trx"];
500	  for (const path of requiredFiles) assert.ok(Object.hasOwn(evidence.files, path), `required report archive member is missing: ${path}`);
501	  const manifestPaths = new Set();
502	  assert.equal(evidence.manifest.effort, "medium", "manifest effort is not medium");
503	  for (const agent of PARTICIPANTS) {
504	    assert.equal(evidence.manifest.targets[agent].effort, "medium", `${agent} manifest effort is not medium`);
505	    assert.ok(evidence.manifest.targets[agent].version.trim(), `${agent} executable version is missing`);
506	  }
507	  for (const sourceFile of evidence.manifest.sourceFiles) {
508	    assert.ok(Object.hasOwn(evidence.sourceFiles, sourceFile.path), `tested source file is missing: ${sourceFile.path}`);
509	    assert.equal(sourceFile.size, Buffer.byteLength(evidence.sourceFiles[sourceFile.path], "utf8"), `tested source size mismatch: ${sourceFile.path}`);
510	    assert.equal(sourceFile.sha256, sha256(evidence.sourceFiles[sourceFile.path]), `tested source hash mismatch: ${sourceFile.path}`);
511	  }
512	  for (const entry of evidence.manifest.entries) {
513	    assert.ok(!manifestPaths.has(entry.path), "duplicate manifest path");
514	    manifestPaths.add(entry.path);
515	    assert.ok(Object.hasOwn(evidence.files, entry.path), `manifest path is missing: ${entry.path}`);
516	    assert.equal(entry.size, Buffer.byteLength(evidence.files[entry.path], "utf8"), `manifest size mismatch: ${entry.path}`);
517	    assert.equal(entry.sha256, sha256(evidence.files[entry.path]), `manifest hash mismatch: ${entry.path}`);
518	  }
519	  assert.equal(manifestPaths.size, Object.keys(evidence.files).length, "manifest does not cover every retained file");
520	  assert.equal(evidence.archive.readable, true, "archive is unreadable");
521	  assert.match(evidence.archive.sha256, /^[A-F0-9]{64}$/u, "archive SHA-256 is invalid");
522	  assert.equal(new Set(evidence.archive.members).size, evidence.archive.members.length, "archive contains duplicate members");
523	  for (const path of [...Object.keys(evidence.files), "manifest.json"]) assert.ok(evidence.archive.members.includes(path), `archive member is missing: ${path}`);
524	  assert.equal(evidence.archive.validationReceipt.zipSha256, evidence.archive.sha256, "archive receipt hash mismatch");
525	  assert.equal(evidence.archive.validationReceipt.memberCount, evidence.archive.members.length, "archive receipt member count mismatch");
526	  assert.deepStrictEqual(
527	    [...evidence.archive.validationReceipt.members].sort(),
528	    [...evidence.archive.members].sort(),
529	    "archive receipt member set mismatch",
530	  );
531	  assert.equal(evidence.archive.validationReceipt.status, evidence.manifest.status, "archive receipt status mismatch");
532	  assert.deepStrictEqual(
533	    evidence.archive.validationReceipt.checks,
534	    ["zip-readable", "member-set-exact", "manifest-hash", "member-size", "member-sha256", "tested-source-hash"],
535	    "archive receipt checks are incomplete",
536	  );
537	  assert.equal(evidence.archive.validationReceipt.sourceFileCount, evidence.manifest.sourceFiles.length, "tested source count mismatch");
538	  assert.ok(evidence.archive.validationReceipt.validatedAt >= evidence.manifest.completedAt, "archive receipt predates the completed manifest");
539	  const summary = JSON.parse(evidence.files["summary.json"]);
540	  assert.equal(summary.status, evidence.manifest.status, "archive summary status differs from manifest status");
541	  const retainedSessions = JSON.parse(evidence.files["sessions.json"]);
542	  const transcriptPaths = Object.keys(evidence.files).filter((path) => /^sessions\/(claude|codex|grok|cline)\/Q0[1-5]\/(answer|review)\.jsonl$/u.test(path));
543	  assert.equal(summary.counts.sessions, retainedSessions.length, "archive summary session count differs from sessions.json");
544	  assert.deepStrictEqual(new Set(transcriptPaths), new Set(retainedSessions.map(({ transcriptPath }) => transcriptPath)), "retained transcript inventory differs from sessions.json");
545	  const orchestration = parseJsonLines(evidence.files["orchestration.jsonl"], "archive orchestration");
546	  for (const session of retainedSessions) {
547	    const pair = orchestration.filter(({ sessionId }) => sessionId === session.sessionId);
548	    assert.equal(pair.length, 2, `retained session orchestration pair is incomplete: ${session.sessionId}`);
549	    assert.ok(pair.some(({ direction }) => direction === "request"), `retained session orchestration request is missing: ${session.sessionId}`);
550	    assert.ok(pair.some(({ direction }) => direction === "response"), `retained session orchestration result is missing: ${session.sessionId}`);
551	  }
552	  if (evidence.manifest.status === "passed") {
553	    const questions = JSON.parse(evidence.files["questions.json"]);
554	    assert.deepStrictEqual(questions, evidence.fixture, "passed archive questions differ from the canonical fixture");
555	    assert.deepStrictEqual(summary.counts, EXPECTED_COUNTS, "passed archive summary counts are wrong");
556	  } else {
557	    assert.ok(Object.hasOwn(evidence.files, "run-failure.json"), "failed archive has no run-failure.json");
558	    assert.equal(summary.status, "failed", "failed archive summary is not failed");
559	  }
560	}
561	
562	/** Validate the complete deterministic test-side contract. */
563	export function assertFourAgentEvidence(evidence) {
564	  assertFourAgentCoreEvidence(evidence);
565	  assertFourAgentArchiveEvidence(evidence);
566	}
