[CmdletBinding()]
param()
Set-Location 'F:\GitHub\frenemy'
Add-Type -AssemblyName System.IO.Compression.FileSystem
function Get-BlobSha256([string]$Path) {
    $tmp = [IO.Path]::GetTempFileName()
    try {
        $p = Start-Process git -ArgumentList @('cat-file', '-p', "HEAD:$Path") -NoNewWindow -Wait -PassThru -RedirectStandardOutput $tmp
        if ($p.ExitCode -ne 0) { return 'NOT-IN-HEAD' }
        (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash
    }
    finally { Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue }
}
foreach ($run in 'TestResults/20261107T201715-four-agent-r10-final-live', 'TestResults/20261107T200437-four-agent-r10-missing-session-metadata') {
    "===== $run"
    $zip = Get-ChildItem -LiteralPath $run -Recurse -Filter 'four-agent-reasoning-review.zip' | Select-Object -First 1
    '  zip={0} sha256={1}' -f $zip.FullName.Substring(18), (Get-FileHash -LiteralPath $zip.FullName).Hash
    $archive = [IO.Compression.ZipFile]::OpenRead($zip.FullName)
    try {
        $entries = @($archive.Entries)
        '  members={0} unique={1}' -f $entries.Count, (@($entries.FullName | Sort-Object -Unique)).Count
        $mEntry = $entries | Where-Object FullName -eq 'manifest.json'
        $reader = [IO.StreamReader]::new($mEntry.Open())
        $mText = $reader.ReadToEnd(); $reader.Dispose()
        $manifest = $mText | ConvertFrom-Json
        '  manifest sha256={0} gitHead={1} host={2} status={3}' -f ([BitConverter]::ToString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($mText))).Replace('-', '')), $manifest.gitHead, $manifest.host, $manifest.status
        '  targets: ' + (($manifest.targets.PSObject.Properties | ForEach-Object { '{0}:{1}/{2}' -f $_.Name, $_.Value.version, $_.Value.effort }) -join '; ')
        $mismatch = 0
        foreach ($e in $manifest.entries) {
            $ze = $entries | Where-Object FullName -eq $e.path
            if (-not $ze) { $mismatch++; "  MISSING member $($e.path)"; continue }
            $ms = [IO.MemoryStream]::new(); $s = $ze.Open(); $s.CopyTo($ms); $s.Dispose()
            $bytes = $ms.ToArray()
            $h = [BitConverter]::ToString([Security.Cryptography.SHA256]::HashData($bytes)).Replace('-', '')
            if ($h -ne $e.sha256 -or $bytes.Length -ne $e.size) { $mismatch++; "  MISMATCH $($e.path)" }
        }
        $extra = @($entries.FullName | Where-Object { $_ -ne 'manifest.json' -and $_ -notin $manifest.entries.path })
        '  manifestEntries={0} memberMismatches={1} extraMembers={2}' -f @($manifest.entries).Count, $mismatch, $extra.Count
        foreach ($sf in $manifest.sourceFiles) {
            $head = Get-BlobSha256 $sf.path
            $work = if (Test-Path -LiteralPath $sf.path) { (Get-FileHash -LiteralPath $sf.path).Hash } else { 'MISSING' }
            '  source {0}: manifest={1} head={2} worktree={3}' -f $sf.path, $sf.sha256.Substring(0, 12), ($head.Substring(0, [Math]::Min(12, $head.Length))), $work.Substring(0, [Math]::Min(12, $work.Length))
        }
        foreach ($name in 'summary.json', 'peer-judgments.json', 'sessions.json', 'answers.json') {
            $ze = $entries | Where-Object FullName -eq $name
            if ($ze) {
                $reader = [IO.StreamReader]::new($ze.Open()); $t = $reader.ReadToEnd(); $reader.Dispose()
                $o = $t | ConvertFrom-Json
                switch ($name) {
                    'summary.json' { '  summary status={0} counts={1} minAccuracy={2}' -f $o.status, ($o.counts | ConvertTo-Json -Compress), $o.minimumAccuracy }
                    'peer-judgments.json' {
                        $j = @($o)
                        $self = @($j | Where-Object { $_.subjectAgent -eq $_.reviewerAgent }).Count
                        $keys = @($j | ForEach-Object { '{0}:{1}:{2}' -f $_.questionId, $_.subjectAgent, $_.reviewerAgent } | Sort-Object -Unique).Count
                        $low = @($j | Where-Object { $_.accuracy -lt 50 }).Count
                        $perAnswer = $j | Group-Object questionId, subjectAgent | ForEach-Object { @($_.Group.reviewerAgent | Sort-Object -Unique).Count }
                        $perAnswerBad = @($perAnswer | Where-Object { $_ -ne 3 }).Count
                        $min = ($j | Measure-Object accuracy -Minimum).Minimum
                        '  judgments={0} uniqueKeys={1} self={2} below50={3} min={4} answersWithout3DistinctReviewers={5} answerGroups={6}' -f $j.Count, $keys, $self, $low, $min, $perAnswerBad, @($perAnswer).Count
                    }
                    'sessions.json' {
                        $s = @($o)
                        $byAgent = ($s | Group-Object agent | ForEach-Object { '{0}={1}' -f $_.Name, $_.Count }) -join ','
                        $nonMedium = @($s | Where-Object { $_.effort -ne 'medium' -or $_.requestedConfiguration.effort -ne 'medium' }).Count
                        $status = ($s | Group-Object status | ForEach-Object { '{0}={1}' -f $_.Name, $_.Count }) -join ','
                        $transcripts = @($s | Where-Object { $entries.FullName -contains $_.transcriptPath }).Count
                        '  sessions={0} byAgent={1} nonMedium={2} status={3} transcriptsPresent={4}' -f $s.Count, $byAgent, $nonMedium, $status, $transcripts
                    }
                    'answers.json' { '  answers={0}' -f @($o).Count }
                }
            }
        }
    }
    finally { $archive.Dispose() }
}

